56","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_SUCCESSOR_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_VALIDATED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_CURATION_DRAFT_CREATED|taxonomy_curation":{"sourceReleaseId":"uuid","initialCuration":"bool","actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_RETIRED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_CREATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_RUNTIME_SETTING_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_CREATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_UPDATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_DELETED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_IMPORT|taxonomy_curation":{"rows":"int","created":"int","updated":"int","errors":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_GRID_SAVE|taxonomy_curation":{"created":"int","updated":"int","retired":"int","groupsCreated":"int","groupsUpdated":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_PUBLISHED|taxonomy_curation":{"snapshotSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_INITIALIZED|taxonomy_curation":{"seedSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_CNAE_ORIGINS_IMPORTED