AT_RULES_DRAFT_SAVED|anatomy_rules":{"draftId":"uuid","revision":"int","profileSetHash":"sha256","exampleSetHash":"sha256"},"ANAT_RULES_CANDIDATE_FROZEN|anatomy_rules":{"candidateId":"uuid","draftId":"uuid","profileSetHash":"sha256","exampleSetHash":"sha256","engineHash":"sha256"},"ANAT_RULES_SIMULATED|anatomy_rules":{"simulationId":"uuid","candidateId":"uuid","reportHash":"sha256","status":["COMPLETE","PARTIAL","CANCELLED","FAILED"],"passCount":"int","failCount":"int","partialCount":"int","cancelledCount":"int","inconclusiveCount":"int"},"ANAT_RULES_COMPARED|anatomy_rules":{"comparisonId":"uuid","candidateId":"uuid","comparisonHash":"sha256","baselineProfileSetHash":"sha256","differenceCount":"int"},"ANAT_RULES_REVIEWED|anatomy_rules":{"reviewId":"uuid","candidateId":"uuid","simulationId":"uuid","outcome":["APPROVED","REJECTED"],"comparisonCount":"int","decisionCount":"int"},"ANAT_RULES_ACTIVATION_PREVIEWED|anatomy_rules":{"previewId":"uuid","candidateId":"uuid","reviewId":"uuid","action":["ACTIVATE","ROLLBACK"],"intentHash":"sha256","expiresMinutes":"int"},"ANAT_RULES_ACTIVATED|anatomy_rules":{"activationId":"uuid","previousActivationId":"uuid","candidateId":"uuid","reviewId":"uuid","previewId":"uuid","action":["ACTIVATE","ROLLBACK"]},"ANAT_RULES_ATTEMPT_REJECTED|anatomy_rules":{"operation":["DRAFT_SAVE","FREEZE","SIMULATE","COMPARE","REVIEW","PREVIEW","CONFIRM"],"code":["STALE_REVISION","AUTHOR_CANNOT_REVIEW","REVIEW_INCOMPLETE","SIMULATION_NOT_PASSING","COMPARISON_MISMATCH","PREVIEW_EXPIRED","PREVIEW_CONSUMED","PREVIEW_STALE","ENGINE_MISMATCH","SIMULATION_UNAVAILABLE","LIMIT_EXCEEDED"],"targetId":"uuid"}}$json$::jsonb;
 IF EXISTS (SELECT 1 FROM jsonb_each(old) o WHERE nxt -> o.key IS DISTINCT FROM o.value)
  OR EXISTS (SELECT 1 FROM jsonb_object_keys(nxt) k WHERE NOT (old ? k) AND k NOT LIKE 'ANAT\_RULES\_%')
 THEN RAISE EXCEPTION 'M_AUDIT_ANAT: audit_event_policy in force differs from the policy this migration extends; rebase it';
 END IF;
END $$;
CREATE OR REPLACE FUNCTION public.audit_event_policy(p_action TEXT,p_type TEXT)
RETURNS JSONB LANGUAGE SQL IMMUTABLE SET search_path=pg_catalog AS $policy$
 SELECT $json${"COMPANY_CREATED|company":{"company_id":"uuid","is_active":"bool","version":"int","actor_redacted":"bool"},"COMPANY_UPDATED|company":{"company_id":"uuid","is_active":"bool","version":"int","actor_redacted":"bool"},"COMPANY_PURGED|company":{"purged":"bool","actor_redacted":"bool"},"ESTABLISHMENT_CREATED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"ESTABLISHMENT_UPDATED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"ESTABLISHMENT_DELETED|establishment":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"COMPANY_TAX_PROFILE_UPDATED|company_tax_profile":{"company_id":"uuid","version":"int","actor_redacted":"bool"},"COMPANY_PRODUCT_PROFILE_UPDATED|company_product_profile":{"company_id":"uuid","is_active":"bool","actor_redacted":"bool"},"PLATFORM_ROLE_GRANTED|platform_user_role":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_REVOKED|platform_user_role":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_GRANTED|app_user":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"PLATFORM_ROLE_REVOKED|app_user":{"role":["PLATFORM_ADMIN","TAXONOMY_CURATOR"],"actor_redacted":"bool"},"COLLECTION_FILTER_DRAFT_SAVED|collection_filter_policy":{"version":"int","revision":"int","actor_redacted":"bool"},"COLLECTION_FILTER_SIMULATION_REQUESTED|collection_filter_simulation":{"policyId":"uuid","version":"int","revision":"int","scope":["FULL_ARCHIVE","RECENT"],"reviewMode":["ALL","SAMPLE","NONE"],"actor_redacted":"bool"},"COLLECTION_FILTER_POLICY_APPROVED|collection_filter_policy":{"version":"int","revision":"int","simulationId":"uuid","actor_redacted":"bool"},"COLLECTION_FILTER_DIRECT_ADMIN_EDIT|collection_filter_policy":{"policyRevision":"int","action":["RULE_KEEP","RULE_DELETE","TERM_PUT","TERM_DELETE","ALIAS_PUT","ALIAS_DELETE","NEWTYPE_MERGE","NEWTYPE_KEEP"],"actor_redacted":"bool"},"COLLECTION_FILT