56","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_SUCCESSOR_PUBLISHED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_RELEASE_VALIDATED|taxonomy_release":{"manifestSha256":"sha256","snapshotSha256":"sha256","sourceReleaseId":"uuid","status":["DRAFT","PUBLISHED"],"actor_redacted":"bool"},"TAXONOMY_CURATION_DRAFT_CREATED|taxonomy_curation":{"sourceReleaseId":"uuid","initialCuration":"bool","actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_DIMENSION_RETIRED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_CREATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_CONCEPT_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_RUNTIME_SETTING_UPDATED|taxonomy_curation":{"actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_CREATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_UPDATED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_GROUP_DELETED|taxonomy_curation":{"groupId":"uuid","actor_redacted":"bool"},"TAXONOMY_CURATION_IMPORT|taxonomy_curation":{"rows":"int","created":"int","updated":"int","errors":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_GRID_SAVE|taxonomy_curation":{"created":"int","updated":"int","retired":"int","groupsCreated":"int","groupsUpdated":"int","actor_redacted":"bool"},"TAXONOMY_CURATION_PUBLISHED|taxonomy_curation":{"snapshotSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_INITIALIZED|taxonomy_curation":{"seedSha256":"sha256","actor_redacted":"bool"},"F2_T02_ACTUACAO_CNAE_ORIGINS_IMPORTED|taxonomy_curation":{"sourceSha256":"sha256","projectionSha256":"sha256","originCount":"int","publicationRequested":"bool","actor_redacted":"bool"},"TAXONOMY_F2_SUGGESTIONS_CHANGED|taxonomy_curation":{"productsCount":"int","ncmsCount":"int","actor_redacted":"bool"},"F2_TAB03_CNAE_ACTUACOES_CHANGED|taxonomy_curation":{"published":"bool","actor_redacted":"bool"},"OFFICIAL_CATALOG_IMPORTED|official_catalog_edition":{"editionId":"uuid","inserted":"int","updated":"int","total":"int","sourceSha256":"sha256","actor_redacted":"bool"},"PUBLICATION_TAG_CURATED|publication":{"action":["ADD","REMOVE","RESTORE"],"actor_redacted":"bool"},"PUBLICATION_PRESENTATION_REFRESHED|publication_version":{"savedPageSha256":"sha256","htmlChars":"int","effectiveUntil":"date","actor_redacted":"bool"},"TAXONOMY_V1_1_DRAFT_CREATED|taxonomy_release":{"sourceReleaseId":"uuid","actor_redacted":"bool"},"TAXONOMY_V1_1_PUBLISHED|taxonomy_release":{"artifactSha256":"sha256","actor_redacted":"bool"},"MERGE_RFB_NORMAS_DOU_HISTORICAL|publication":{"douPublicationId":"uuid","rfbPublicationId":"uuid","douIdentityHash":"sha256","rfbIdentityHash":"sha256","publicationId":"uuid","identityHash":"sha256","rfbExternalId":["153678","153667","153640","153663","153636","153191","153192","153193","153120","153046","153059"],"douExternalId":["2026-09-23:DO1:180:24398395","2026-09-23:DO1:180:24398396","2026-09-22:DO1:179:24392992","2026-09-22:DO1E:179-B:24391984","2026-09-21:DO1E:178-B:24386620","2026-08-31:DO1:164:24304745","2026-08-31:DO1:164:24302161","2026-08-31:DO1:164:24302159","2026-08-26:DO1:161:24286739","2026-08-24:DO1:159:24272929","2026-08-24:DO1E:159-B:24280394"],"origins":"rfb_dou_origins","actor_redacted":"bool"},"TAXONOMY_CURATION_SECTOR_ALIASES_CLEARED|taxonomy_curation":{"removedSynonyms":"int","rowsAffected":"int","actor_redacted":"bool"},"TAXONOMY_DRAFT_ORPHAN_RELATIONS_REMOVED|taxonomy_release":{"removedCount":"int","removedRelationIds":"uuids","preservedHistory":"bool","actor_redacted":"bool"},"ANAT_RULES_DRAFT_SAVED|anatomy_rules":{"draftId":"uuid","revision":"int","profileSetHash":"sha256","exampleSetHash":"sha256"},"ANAT_RULES_CANDIDATE_FROZEN|anatomy_rules":{"candidateId":"uuid","draftId":"uuid","profileSetHash":"sha256","exampleSetHash":"sha256","engineHash":"sha256"},"ANAT_RULES_SIMULATED|anatomy_rules":{"simulationId":"uuid","candidateId":"uuid","reportHash":"sha256","status":["COMPLETE","PARTIAL","CANCELLED","FAILED"],"passCount":"int","failCount":"int","partialCount":"int","cancelledCount":"int","inconclusiveCount":"int"},"ANAT_RULES_COMPARED|anatomy_rules":{"comparisonId":"uuid","candidateId":"uuid","comparisonHash":"sha256","baselineProfileSetHash":"sha256","differenceCount":"int"},"ANAT_RULES_REVIEWED|anatomy_rules":{"reviewId":"uuid","candidateId":"uuid","simulationId":"uuid","outcome":["APPROVED","REJECTED"],"comparisonCount":"int","decisionCount":"int"},"ANAT_RULES_ACTIVATION_PREVIEWED|anatomy_rules":{"previewId":"uuid","candidateId":"uuid","reviewId":"uuid","action":["ACTIVATE","ROLLBACK"],"intentHash":"sha256","expiresMinutes":"int"},"ANAT_RULES_ACTIVATED|anatomy_rules":{"activationId":"uuid","previousActivationId":"uuid","candidateId":"uuid","reviewId":"uuid","previewId":"uuid","action":["ACTIVATE","ROLLBACK"]},"ANAT_RULES_ATTEMPT_REJECTED|anatomy_rules":{"operation":["DRAFT_SAVE","FREEZE","SIMULATE","COMPARE","REVIEW","PREVIEW","CONFIRM"],"code":["STALE_REVISION","AUTHOR_CANNOT_REVIEW","REVIEW_INCOMPLETE","SIMULATION_NOT_PASSING","COMPARISON_MISMATCH","PREVIEW_EXPIRED","PREVIEW_CONSUMED","PREVIEW_STALE","ENGINE_MISMATCH","SIMULATION_UNAVAILABLE","LIMIT_EXCEEDED"],"targetId":"uuid"}}$json$::jsonb -> (p_action||'|'||p_type)
$policy$;

-- Global ANAT events (tenant_id NULL) are invisible to the tenant policies of 009. B1-R1-03 boundary:
-- * INSERT: only the dedicated NOLOGIN role anat_rules_writer (owner of the audited entry functions), only ADMIN rows of
--   anatomy_rules / ANAT_RULES_*, actor = session user, and that user must be an active PLATFORM_ADMIN (036 predicate).
--   radar_app gets NO insert policy for these rows: it can write them only through the entry functions.
-- * SELECT: radar_app only when the session user is an active PLATFORM_ADMIN.
-- Policies of other fronts are untouched. Because 009 (worker) and 018 (curator) already grant broad tenant_id NULL
-- access, two RESTRICTIVE policies scoped to ANAT rows only (they AND with every permissive policy, they change nothing
-- for any other event): ANAT rows are inserted only by anat_rules_writer and read only by radar_app (admin-gated below).
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anat_rules_writer') THEN
  CREATE ROLE anat_rules_writer NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS NOINHERIT;
 END IF;
END $$;
GRANT USAGE ON SCHEMA public TO anat_rules_writer;
GRANT INSERT ON audit_log TO anat_rules_writer;
CREATE POLICY audit_log_anat_rules_writer_insert ON audit_log FOR INSERT TO anat_rules_writer
 WITH CHECK (tenant_id IS NULL AND actor_type = 'ADMIN' AND entity_type = 'anatomy_rules'
  AND action LIKE 'ANAT\_RULES\_%' AND actor_id = app_current_user_id()::text AND app_user_is_platform_admin());
CREATE POLICY audit_log_anat_rules_admin_select ON audit_log FOR SELECT TO radar_app
 USING (tenant_id IS NULL AND entity_type = 'anatomy_rules' AND app_user_is_platform_admin());
CREATE POLICY audit_log_anat_rules_writer_only ON audit_log AS RESTRICTIVE FOR INSERT TO PUBLIC
 WITH CHECK ((action NOT LIKE 'ANAT\_RULES\_%' AND entity_type IS DISTINCT FROM 'anatomy_rules') OR current_user = 'anat_rules_writer');
CREATE POLICY audit_log_anat_rules_hidden ON audit_log AS RESTRICTIVE FOR SELECT TO radar_worker, radar_taxonomy_curator
 USING (entity_type IS DISTINCT FROM 'anatomy_rules');
